use super::*;

/// The probe: RUN the binary that `current` now points at, on the device.
///
/// This is the only step that can tell you the deploy actually worked. A symlink swap always succeeds;
/// executing the result is what catches an architecture mismatch, a glibc that is too old, and a
/// transfer that verified but landed on a full disk.
pub fn probe(device: &Device, name: &str) -> (bool, String) {
    match ssh(device, &probe_script(name)) {
        // The script always exits 0 and REPORTS the binary's status in its output, so a non-zero
        // binary and an unreachable device stay distinguishable — they need different words.
        Ok(out) => read_probe(&out),
        Err(e) => (false, format!("could not reach the device to probe it: {e}")),
    }
}
